// Not cryptographic -- a stable content fingerprint used only to detect a
// stale or mismatched publish approval (see publication-policy.json).
function fnv1a32(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = (h + ((h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24))) >>> 0;
  }
  return h.toString(16).padStart(8, '0');
}
const requestId = $('Review Trigger Webhook').first().json.body.request_id;
const manifest = ($json.contract.stage_artifacts && $json.contract.stage_artifacts.build_manifest) || [];
const sorted = [...manifest].sort((a, b) => String(a.artifact_key).localeCompare(String(b.artifact_key)));
const checksum = 'fnv1a32:' + fnv1a32(JSON.stringify(sorted));
return [{ json: { request_id: requestId, build_checksum: checksum, manifest: sorted, contract: $json.contract } }];

const ctx = $('Compute Build Checksum').first().json;
const requestId = ctx.request_id;
const manifest = ctx.manifest;
const contract = ctx.contract;
let livePosts = [];
try {
  const response = $('List Live Posts').first().json;
  const parsed = JSON.parse(response.result.content[0].text);
  livePosts = Array.isArray(parsed) ? parsed : (parsed.posts || []);
} catch (e) { livePosts = []; }
let elementorInspection = { blocking: true, pages: [] };
try { elementorInspection = JSON.parse($('Inspect Elementor Build').first().json.result.content[0].text); } catch (e) {}
const visual = $json.manifest || {};
const captures = Array.isArray(visual.captures) ? visual.captures : [];
const placeholderPatterns = [/\{\{[^}]*\}\}/, /\bTODO\b/, /\bTBD\b/, /\[a completer\]/i, /\[a confirmer\]/i];
const findings = [];
const requiredPages = (contract.site && Array.isArray(contract.site.pages) && contract.site.pages.length) ? contract.site.pages : [];
const manifestKeys = new Set(manifest.map(m => m.artifact_key));
const missingPages = requiredPages.filter(p => !manifestKeys.has(p));
if (missingPages.length) findings.push({ artifact_key: '', severity: 'critical', category: 'contract_conformance', evidence: 'Missing manifest entries for: ' + missingPages.join(', '), expected_correction: 'Build the missing pages before requesting review again.' });
for (const m of manifest.filter(m => m.verified !== true)) findings.push({ artifact_key: m.artifact_key, severity: 'critical', category: 'content', evidence: 'Manifest entry was not verified at build time (verified=' + m.verified + ')', expected_correction: 'Rebuild this artifact so the read-back verification passes.' });
for (const post of livePosts) {
  const text = (post.title || '') + ' ' + (post.content || post.excerpt || '');
  const hit = placeholderPatterns.find(p => p.test(text));
  if (hit) findings.push({ artifact_key: post.slug || String(post.ID || post.id || ''), severity: 'critical', category: 'placeholder', evidence: 'Live content matches placeholder pattern ' + hit, expected_correction: 'Replace the placeholder with real content.' });
}
for (const page of elementorInspection.pages || []) for (const finding of page.findings || []) findings.push({ artifact_key: manifest.find(m => m.post_id === page.post_id)?.artifact_key || '', severity: finding.severity || 'major', category: 'elementor', evidence: `${finding.code || 'elementor_check_failed'} on post ${page.post_id}`, expected_correction: 'Correct only the reported Elementor element and re-run inspection.' });
if (elementorInspection.blocking && !(elementorInspection.pages || []).length) findings.push({ artifact_key: '', severity: 'critical', category: 'elementor', evidence: 'Elementor inspection did not return any page report', expected_correction: 'Restore readable Elementor page documents before review.' });
const expectedCaptureCount = manifest.length * 3;
if (!visual.ok || captures.length !== expectedCaptureCount || captures.some(c => c.ok !== true)) findings.push({ artifact_key: '', severity: 'major', category: 'visual', evidence: `Visual evidence incomplete: ${captures.filter(c => c.ok).length}/${expectedCaptureCount} captures succeeded`, expected_correction: 'Capture successful desktop, tablet and mobile evidence for every built page.' });
return [{ json: { request_id: requestId, deterministic_findings: findings, deterministic_pass: findings.length === 0, manifest, elementor_inspection: elementorInspection, visual_manifest: visual, contract, build_checksum: ctx.build_checksum, live_posts_count: livePosts.length } }];

const parsed = ($json.parsed_json && typeof $json.parsed_json === 'object') ? $json.parsed_json : null;
const allowedSeverities = new Set(['minor', 'major', 'critical']);
const allowedCategories = new Set(['content', 'navigation', 'forms', 'accessibility', 'seo', 'performance', 'security', 'contract']);
const verdict = parsed && parsed.verdict === 'approve' ? 'approve' : 'changes_requested';
const findings = [];
const seen = new Set();
for (const raw of (parsed && Array.isArray(parsed.findings) ? parsed.findings : [])) {
  const artifactKey = String(raw.artifact_key || '').trim();
  const severity = allowedSeverities.has(raw.severity) ? raw.severity : 'major';
  const category = allowedCategories.has(raw.category) ? raw.category : 'contract';
  const evidence = String(raw.evidence || '').trim();
  const expectedCorrection = String(raw.expected_correction || '').trim();
  if (!artifactKey || !evidence || !expectedCorrection) continue;
  const dedupeKey = [artifactKey, severity, category, evidence].join('|');
  if (seen.has(dedupeKey)) continue;
  seen.add(dedupeKey);
  findings.push({ artifact_key: artifactKey, severity, category, evidence, expected_correction: expectedCorrection });
  if (findings.length >= 30) break;
}
const hasBlocking = findings.some((finding) => finding.severity === 'major' || finding.severity === 'critical');
const agentVerdict = hasBlocking ? 'changes_requested' : verdict;
return [{ json: { agent_verdict: agentVerdict, agent_findings: findings } }];

const det = $('Run Deterministic Checks').first().json;
const agent = $json;
const findings = [...det.deterministic_findings, ...agent.agent_findings];
const hasBlocking = findings.some((finding) => finding.severity === 'major' || finding.severity === 'critical');
// Deterministic checks always win. Major and critical findings block approval.
const verdict = (det.deterministic_pass && agent.agent_verdict === 'approve' && !hasBlocking) ? 'approve' : 'changes_requested';
return [{ json: {
  request_id: det.request_id,
  verdict,
  findings,
  build_checksum: det.build_checksum,
  deterministic_pass: det.deterministic_pass,
  agent_verdict: agent.agent_verdict
} }];
